  income_category text,
  unallocated_amount numeric(14,2) NOT NULL DEFAULT 0 CHECK (unallocated_amount >= 0),
  notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
