    v_salary := NULL;
    v_start_date := NULL;
  END IF;

  UPDATE public.members
  SET compensation_type = v_type,
      monthly_salary = v_salary,
      salary_start_date = v_start_date,
      updated_at = now(),
      updated_by = v_member_id
  WHERE id = p_staff_id;

  RETURN jsonb_build_object(
    'success', true,
    'staff_id', p_staff_id,
    'compensation_type', v_type,
