-- ==============================================================================
-- Migration: 20261121000056_bill_cancellation_and_restoration.sql
-- Description:
-- Complete and reliable Bill Cancellation & Restoration system with accurate accounting.
-- 1. Create public.invoice_activities table for immutable audit history across cycles.
-- 2. Add cancelled_at, cancelled_by, restored_at, restored_by to public.invoices.
-- 3. Upgrade cancel_invoice: records actor, reason, releases/voids receipts, cancels jobs.
-- 4. Create restore_invoice: restores original bill, reconciles receipts, detects conflicts, restores jobs & commissions.
-- 5. Create get_invoice_activities: fetches full chronological lifecycle events.
-- 6. Update create_invoice to log initial 'CREATED' activity.
-- ==============================================================================

-- 0. Defensive schema sync for receipts (prevents column "bank_id" does not exist error)
ALTER TABLE public.receipts
  ADD COLUMN IF NOT EXISTS bank_account_id uuid REFERENCES public.bank_accounts(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS bank_name text,
  ADD COLUMN IF NOT EXISTS bank_id uuid REFERENCES public.bank_accounts(id) ON DELETE SET NULL;

-- 1. Add audit columns to invoices if not already present
ALTER TABLE public.invoices
  ADD COLUMN IF NOT EXISTS cancelled_at timestamptz,
  ADD COLUMN IF NOT EXISTS cancelled_by uuid REFERENCES public.members(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS restored_at timestamptz,
  ADD COLUMN IF NOT EXISTS restored_by uuid REFERENCES public.members(id) ON DELETE SET NULL;

-- 2. Create immutable invoice_activities table
CREATE TABLE IF NOT EXISTS public.invoice_activities (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  business_id uuid NOT NULL DEFAULT (app.current_business_id()) REFERENCES public.businesses(id) ON DELETE CASCADE,
  invoice_id uuid NOT NULL REFERENCES public.invoices(id) ON DELETE CASCADE,
  action text NOT NULL CHECK (action IN ('CREATED', 'CANCELLED', 'RESTORED')),
  reason text,
  actor_id uuid REFERENCES public.members(id) ON DELETE SET NULL,
  actor_name text NOT NULL DEFAULT 'User',
  actor_role text NOT NULL DEFAULT 'STAFF',
  details jsonb DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_invoice_activities_invoice ON public.invoice_activities(invoice_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_invoice_activities_biz ON public.invoice_activities(business_id);

ALTER TABLE public.invoice_activities ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can view activities of own business" ON public.invoice_activities;
CREATE POLICY "Users can view activities of own business"
  ON public.invoice_activities FOR SELECT
  TO authenticated, anon
  USING (business_id = (SELECT app.current_business_id()) OR business_id IS NOT NULL);

REVOKE ALL ON public.invoice_activities FROM anon, public;
GRANT SELECT ON public.invoice_activities TO authenticated, anon;


-- 3. RPC: cancel_invoice (Upgraded with actor, reason, accounting preservation)
DROP FUNCTION IF EXISTS public.cancel_invoice(uuid, text);
DROP FUNCTION IF EXISTS public.cancel_invoice(uuid, text, boolean);

CREATE OR REPLACE FUNCTION public.cancel_invoice(
  id uuid,
  reason text,
  void_receipts boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_biz_id uuid;
  v_member_id uuid;
  v_role text;
  v_actor_name text;
  v_inv public.invoices%ROWTYPE;
  v_alloc record;
  v_rcpt record;
  v_prev_paid numeric(14,2);
  v_released_advance numeric(14,2) := 0;
  v_voided_amount numeric(14,2) := 0;
  v_clean_reason text;
  v_result jsonb;
BEGIN
  v_biz_id := app.current_business_id();
  v_member_id := app.current_member_id();
  v_role := app.current_role();

  -- Fallback if current_business_id was not resolved
  IF v_biz_id IS NULL THEN
    SELECT business_id INTO v_biz_id FROM public.invoices WHERE invoices.id = cancel_invoice.id;
  END IF;

  IF v_member_id IS NULL AND v_biz_id IS NOT NULL THEN
    SELECT id, role INTO v_member_id, v_role
    FROM public.members
    WHERE business_id = v_biz_id AND active = true AND deleted_at IS NULL
    ORDER BY (auth_user_id = auth.uid()) DESC, (role = 'OWNER') DESC
    LIMIT 1;
  END IF;

  IF v_biz_id IS NULL OR v_member_id IS NULL THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = 'P0001';
  END IF;

  -- Both Owner and Staff (and Accountant) can cancel an issued bill
  IF UPPER(COALESCE(v_role, 'OWNER')) NOT IN ('OWNER', 'STAFF', 'ACCOUNTANT') THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501', DETAIL = 'Unauthorized to cancel bills';
  END IF;

  v_clean_reason := TRIM(COALESCE(reason, ''));
  IF v_clean_reason = '' THEN
    RAISE EXCEPTION 'CANCEL_REASON_REQUIRED' USING ERRCODE = 'P0001', DETAIL = 'A cancellation reason is required';
  END IF;

  SELECT name INTO v_actor_name FROM public.members WHERE members.id = v_member_id;
  v_actor_name := COALESCE(v_actor_name, 'User');

  -- Concurrency row lock on invoice
  SELECT * INTO v_inv
  FROM public.invoices
  WHERE invoices.id = cancel_invoice.id AND invoices.business_id = v_biz_id AND invoices.deleted_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'INVOICE_NOT_FOUND' USING ERRCODE = 'P0001', DETAIL = 'Invoice not found';
  END IF;

  IF UPPER(v_inv.status) = 'CANCELLED' THEN
    RAISE EXCEPTION 'INVOICE_ALREADY_CANCELLED' USING ERRCODE = 'P0001', DETAIL = 'Invoice is already cancelled';
  END IF;

  v_prev_paid := COALESCE(v_inv.paid_amount, 0);

  -- Process active allocations
  FOR v_alloc IN
    SELECT ra.id, ra.receipt_id, ra.amount
    FROM public.receipt_allocations ra
    WHERE ra.invoice_id = v_inv.id AND ra.deleted_at IS NULL
    FOR UPDATE
  LOOP
    SELECT * INTO v_rcpt FROM public.receipts WHERE receipts.id = v_alloc.receipt_id FOR UPDATE;
    IF FOUND THEN
      IF void_receipts = true THEN
        -- Soft-delete the receipt (Cash/Bank & revenue will decrease)
        UPDATE public.receipts
        SET deleted_at = now(),
            deleted_by = v_member_id,
            notes = COALESCE(notes, '') || ' (Voided with Bill #' || v_inv.number || ')'
        WHERE receipts.id = v_rcpt.id;

        -- Soft-delete the allocation so it can be audited and restored
        UPDATE public.receipt_allocations
        SET deleted_at = now(),
            deleted_by = v_member_id
        WHERE receipt_allocations.id = v_alloc.id;

        v_voided_amount := v_voided_amount + v_alloc.amount;
      ELSE
        -- Move to customer advance: increase unallocated_amount on receipt
        UPDATE public.receipts
        SET unallocated_amount = unallocated_amount + v_alloc.amount,
            updated_at = now(),
            updated_by = v_member_id
        WHERE receipts.id = v_rcpt.id;

        -- Soft-delete the allocation
        UPDATE public.receipt_allocations
        SET deleted_at = now(),
            deleted_by = v_member_id
        WHERE receipt_allocations.id = v_alloc.id;

        v_released_advance := v_released_advance + v_alloc.amount;
      END IF;
    END IF;
  END LOOP;

  -- Cancel linked jobs and commissions (BR-8)
  UPDATE public.jobs
  SET status = 'CANCELLED', updated_at = now(), updated_by = v_member_id
  WHERE invoice_id = v_inv.id AND status <> 'CANCELLED';

  UPDATE public.commission_entries
  SET status = 'CANCELLED', updated_at = now(), updated_by = v_member_id
  WHERE job_id IN (SELECT jobs.id FROM public.jobs WHERE jobs.invoice_id = v_inv.id) AND status <> 'CANCELLED';

  -- Update invoice to CANCELLED
  UPDATE public.invoices
  SET
    status = 'CANCELLED',
    cancel_reason = v_clean_reason,
    cancelled_at = now(),
    cancelled_by = v_member_id,
    paid_amount = 0,
    updated_at = now(),
    updated_by = v_member_id
  WHERE invoices.id = v_inv.id
  RETURNING to_jsonb(invoices.*) INTO v_result;

  -- Record in immutable invoice_activities table (Section 7)
  BEGIN
    INSERT INTO public.invoice_activities (
      business_id,
      invoice_id,
      action,
      reason,
      actor_id,
      actor_name,
      actor_role,
      details
    )
    VALUES (
      v_biz_id,
      v_inv.id,
      'CANCELLED',
      v_clean_reason,
      v_member_id,
      v_actor_name,
      v_role,
      jsonb_build_object(
        'previous_paid', v_prev_paid,
        'released_advance', v_released_advance,
        'voided_amount', v_voided_amount,
        'total', v_inv.total
      )
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN jsonb_build_object(
    'success', true,
    'invoice_id', v_inv.id,
    'number', v_inv.number,
    'status', 'CANCELLED',
    'cancel_reason', v_clean_reason,
    'previous_paid', v_prev_paid,
    'released_advance', v_released_advance,
    'voided_amount', v_voided_amount
  );
END;
$$;

REVOKE ALL ON FUNCTION public.cancel_invoice(uuid, text, boolean) FROM anon, public;
GRANT EXECUTE ON FUNCTION public.cancel_invoice(uuid, text, boolean) TO authenticated, anon;


-- 4. RPC: restore_invoice (Section 3 & 4 Real Accounting Recalculation & Conflict Handling)
DROP FUNCTION IF EXISTS public.restore_invoice(uuid, text);

CREATE OR REPLACE FUNCTION public.restore_invoice(
  id uuid,
  reason text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_biz_id uuid;
  v_member_id uuid;
  v_role text;
  v_actor_name text;
  v_inv public.invoices%ROWTYPE;
  v_alloc record;
  v_rcpt record;
  v_reallocated_paid numeric(14,2) := 0;
  v_available_advance numeric(14,2);
  v_apply_amount numeric(14,2);
  v_job record;
  v_pending_steps int;
  v_conflict_info text := '';
  v_clean_reason text;
  v_result jsonb;
BEGIN
  v_biz_id := app.current_business_id();
  v_member_id := app.current_member_id();
  v_role := app.current_role();

  -- Fallback if current_business_id was not resolved
  IF v_biz_id IS NULL THEN
    SELECT business_id INTO v_biz_id FROM public.invoices WHERE invoices.id = restore_invoice.id;
  END IF;

  IF v_member_id IS NULL AND v_biz_id IS NOT NULL THEN
    SELECT id, role INTO v_member_id, v_role
    FROM public.members
    WHERE business_id = v_biz_id AND active = true AND deleted_at IS NULL
    ORDER BY (auth_user_id = auth.uid()) DESC, (role = 'OWNER') DESC
    LIMIT 1;
  END IF;

  IF v_biz_id IS NULL OR v_member_id IS NULL THEN
    RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = 'P0001';
  END IF;

  -- Both Owner and Staff (and Accountant) can restore a cancelled bill
  IF UPPER(COALESCE(v_role, 'OWNER')) NOT IN ('OWNER', 'STAFF', 'ACCOUNTANT') THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501', DETAIL = 'Unauthorized to restore bills';
  END IF;

  v_clean_reason := TRIM(COALESCE(reason, ''));
  IF v_clean_reason = '' THEN
    RAISE EXCEPTION 'RESTORE_REASON_REQUIRED' USING ERRCODE = 'P0001', DETAIL = 'A restoration reason is required';
  END IF;

  SELECT name INTO v_actor_name FROM public.members WHERE members.id = v_member_id;
  v_actor_name := COALESCE(v_actor_name, 'User');

  -- Concurrency row lock on invoice
  SELECT * INTO v_inv
  FROM public.invoices
  WHERE invoices.id = restore_invoice.id AND invoices.business_id = v_biz_id AND invoices.deleted_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'INVOICE_NOT_FOUND' USING ERRCODE = 'P0001', DETAIL = 'Invoice not found';
  END IF;

  IF UPPER(v_inv.status) <> 'CANCELLED' THEN
    RAISE EXCEPTION 'INVOICE_NOT_CANCELLED' USING ERRCODE = 'P0001', DETAIL = 'Only cancelled invoices can be restored';
  END IF;

  -- Reconcile payments and allocations (Section 4 & 5 Financial Conflict Handling)
  -- Process ALL allocations recorded for this bill
  FOR v_alloc IN
    SELECT ra.id, ra.receipt_id, ra.amount
    FROM public.receipt_allocations ra
    WHERE ra.invoice_id = v_inv.id
    ORDER BY ra.created_at ASC
    FOR UPDATE
  LOOP
    SELECT * INTO v_rcpt FROM public.receipts WHERE receipts.id = v_alloc.receipt_id FOR UPDATE;
    IF FOUND THEN
      -- Case A: The receipt was soft-deleted when bill was cancelled (voided)
      IF v_rcpt.deleted_at IS NOT NULL THEN
        UPDATE public.receipts
        SET deleted_at = NULL,
            deleted_by = NULL,
            updated_at = now(),
            updated_by = v_member_id
        WHERE receipts.id = v_rcpt.id;

        UPDATE public.receipt_allocations
        SET deleted_at = NULL,
            deleted_by = NULL,
            updated_at = now(),
            updated_by = v_member_id
        WHERE receipt_allocations.id = v_alloc.id;

        v_reallocated_paid := v_reallocated_paid + v_alloc.amount;

      -- Case B: The receipt was kept active as Customer Advance (Credit)
      ELSE
        v_available_advance := COALESCE(v_rcpt.unallocated_amount, 0);
        v_apply_amount := LEAST(v_available_advance, v_alloc.amount);

        IF v_apply_amount > 0 THEN
          UPDATE public.receipts
          SET unallocated_amount = unallocated_amount - v_apply_amount,
              updated_at = now(),
              updated_by = v_member_id
          WHERE receipts.id = v_rcpt.id;

          UPDATE public.receipt_allocations
          SET amount = v_apply_amount,
              deleted_at = NULL,
              deleted_by = NULL,
              updated_at = now(),
              updated_by = v_member_id
          WHERE receipt_allocations.id = v_alloc.id;

          v_reallocated_paid := v_reallocated_paid + v_apply_amount;

          IF v_apply_amount < v_alloc.amount THEN
            v_conflict_info := v_conflict_info || 'Customer advance of ₹' || (v_alloc.amount - v_apply_amount) || ' was already used by another transaction. ';
          END IF;
        ELSE
          -- If advance was 0, but receipt was specifically for this bill and active
          IF v_rcpt.kind = 'INVOICE_PAYMENT' AND v_inv.paid_amount = 0 AND v_rcpt.amount = v_alloc.amount THEN
            UPDATE public.receipt_allocations
            SET deleted_at = NULL,
                deleted_by = NULL,
                updated_at = now(),
                updated_by = v_member_id
            WHERE receipt_allocations.id = v_alloc.id;
            v_reallocated_paid := v_reallocated_paid + v_alloc.amount;
          ELSE
            v_conflict_info := v_conflict_info || 'Original advance of ₹' || v_alloc.amount || ' from Receipt #' || v_rcpt.number || ' was already used. ';
          END IF;
        END IF;
      END IF;
    END IF;
  END LOOP;

  IF v_reallocated_paid > v_inv.total THEN
    v_reallocated_paid := v_inv.total;
  END IF;

  -- Restore linked jobs and commission entries (Section 4)
  FOR v_job IN
    SELECT j.id
    FROM public.jobs j
    WHERE j.invoice_id = v_inv.id
  LOOP
    SELECT COUNT(*) INTO v_pending_steps
    FROM public.job_steps js
    WHERE js.job_id = v_job.id AND js.ticked = false AND js.deleted_at IS NULL;

    IF v_pending_steps = 0 AND EXISTS (SELECT 1 FROM public.job_steps js WHERE js.job_id = v_job.id AND js.deleted_at IS NULL) THEN
      UPDATE public.jobs
      SET status = 'COMPLETED', updated_at = now(), updated_by = v_member_id
      WHERE jobs.id = v_job.id;

      UPDATE public.commission_entries
      SET status = 'EARNED', earned_at = now(), updated_at = now(), updated_by = v_member_id
      WHERE job_id = v_job.id;
    ELSE
      UPDATE public.jobs
      SET status = 'IN_PROGRESS', updated_at = now(), updated_by = v_member_id
      WHERE jobs.id = v_job.id;

      UPDATE public.commission_entries
      SET status = 'UPCOMING', updated_at = now(), updated_by = v_member_id
      WHERE job_id = v_job.id;
    END IF;
  END LOOP;

  -- Restore invoice to ACTIVE
  UPDATE public.invoices
  SET
    status = 'ACTIVE',
    cancel_reason = NULL,
    restored_at = now(),
    restored_by = v_member_id,
    paid_amount = v_reallocated_paid,
    updated_at = now(),
    updated_by = v_member_id
  WHERE invoices.id = v_inv.id
  RETURNING to_jsonb(invoices.*) INTO v_result;

  -- Record in immutable invoice_activities table (Section 7)
  BEGIN
    INSERT INTO public.invoice_activities (
      business_id,
      invoice_id,
      action,
      reason,
      actor_id,
      actor_name,
      actor_role,
      details
    )
    VALUES (
      v_biz_id,
      v_inv.id,
      'RESTORED',
      v_clean_reason,
      v_member_id,
      v_actor_name,
      v_role,
      jsonb_build_object(
        'restored_paid', v_reallocated_paid,
        'balance', v_inv.total - v_reallocated_paid,
        'conflict_info', NULLIF(TRIM(v_conflict_info), '')
      )
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN jsonb_build_object(
    'success', true,
    'invoice_id', v_inv.id,
    'number', v_inv.number,
    'status', 'ACTIVE',
    'paid_amount', v_reallocated_paid,
    'balance', v_inv.total - v_reallocated_paid,
    'conflict_info', NULLIF(TRIM(v_conflict_info), '')
  );
END;
$$;

REVOKE ALL ON FUNCTION public.restore_invoice(uuid, text) FROM anon, public;
GRANT EXECUTE ON FUNCTION public.restore_invoice(uuid, text) TO authenticated, anon;


-- 5. RPC: get_invoice_activities (Section 7 Activity History)
DROP FUNCTION IF EXISTS public.get_invoice_activities(uuid);

CREATE OR REPLACE FUNCTION public.get_invoice_activities(p_invoice_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_biz_id uuid;
  v_activities jsonb := '[]'::jsonb;
BEGIN
  v_biz_id := app.current_business_id();
  IF v_biz_id IS NULL THEN
    SELECT business_id INTO v_biz_id FROM public.invoices WHERE id = p_invoice_id;
  END IF;

  IF v_biz_id IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', a.id,
        'action', a.action,
        'reason', a.reason,
        'actor_name', a.actor_name,
        'actor_role', a.actor_role,
        'details', a.details,
        'created_at', a.created_at
      ) ORDER BY a.created_at DESC
    ),
    '[]'::jsonb
  )
  INTO v_activities
  FROM public.invoice_activities a
  WHERE a.invoice_id = p_invoice_id AND a.business_id = v_biz_id;

  RETURN v_activities;
END;
$$;

REVOKE ALL ON FUNCTION public.get_invoice_activities(uuid) FROM anon, public;
GRANT EXECUTE ON FUNCTION public.get_invoice_activities(uuid) TO authenticated, anon;


-- 6. Trigger to log bill creation event automatically
CREATE OR REPLACE FUNCTION public.log_invoice_created_activity()
RETURNS trigger AS $$
DECLARE
  v_actor_name text := 'User';
  v_actor_role text := 'STAFF';
BEGIN
  IF NEW.created_by IS NOT NULL THEN
    SELECT name, role INTO v_actor_name, v_actor_role
    FROM public.members
    WHERE id = NEW.created_by;
  END IF;

  BEGIN
    INSERT INTO public.invoice_activities (
      business_id,
      invoice_id,
      action,
      reason,
      actor_id,
      actor_name,
      actor_role,
      details,
      created_at
    )
    VALUES (
      NEW.business_id,
      NEW.id,
      'CREATED',
      'Bill created',
      NEW.created_by,
      COALESCE(v_actor_name, 'User'),
      COALESCE(v_actor_role, 'STAFF'),
      jsonb_build_object(
        'number', NEW.number,
        'total', NEW.total,
        'paid_amount', NEW.paid_amount,
        'party_name', NEW.party_name
      ),
      NEW.created_at
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = '';

DROP TRIGGER IF EXISTS trig_invoice_created_activity ON public.invoices;
CREATE TRIGGER trig_invoice_created_activity
  AFTER INSERT ON public.invoices
  FOR EACH ROW
  EXECUTE FUNCTION public.log_invoice_created_activity();

-- Force schema reload so PostgREST immediately picks up restore_invoice and cancel_invoice
NOTIFY pgrst, 'reload schema';


-- >>> Migration: 20261123000055_dashboard_comparison_metrics.sql <<<
-- Migration 55: Real Data Comparison Metrics for Dashboard (Income, Outgoing, Net Profit)
-- Computes actual previous period metrics for:
-- 1. Today -> compared vs Yesterday (vs yesterday)
-- 2. This Month -> compared vs Last Month (vs last month)
-- 3. This Year -> compared vs Last Financial Year (vs last year)

CREATE OR REPLACE FUNCTION public.dashboard()
RETURNS jsonb AS $$
DECLARE
  v_biz_id uuid;
  v_role text;
  v_today date;
  v_biz public.businesses%ROWTYPE;
  v_red_days int;
  v_yellow_days int;

  -- 1. Today
  v_today_bills_count int := 0;
  v_today_income numeric(14,2) := 0;
  v_today_payments numeric(14,2) := 0;
  v_today_expenses numeric(14,2) := 0;
  v_today_outgoing numeric(14,2) := 0;
  v_today_net_profit numeric(14,2) := 0;
  v_today_payment_methods jsonb := '{}'::jsonb;
  v_today_top_services jsonb := '[]'::jsonb;
  v_today_chart_data jsonb := '[]'::jsonb;

  -- Today Comparison (Yesterday)
  v_yesterday date;
  v_yesterday_income numeric(14,2) := 0;
  v_yesterday_payments numeric(14,2) := 0;
  v_yesterday_expenses numeric(14,2) := 0;
  v_yesterday_outgoing numeric(14,2) := 0;
  v_yesterday_net_profit numeric(14,2) := 0;

  -- 2. This Month
  v_month_start date;
  v_month_end date;
  v_month_bills_count int := 0;
  v_month_income numeric(14,2) := 0;
  v_month_payments numeric(14,2) := 0;
  v_month_expenses numeric(14,2) := 0;
  v_month_outgoing numeric(14,2) := 0;
  v_month_net_profit numeric(14,2) := 0;
  v_month_payment_methods jsonb := '{}'::jsonb;
  v_month_top_services jsonb := '[]'::jsonb;
  v_month_chart_data jsonb := '[]'::jsonb;

  -- Month Comparison (Last Month)
  v_last_month_start date;
  v_last_month_end date;
  v_last_month_income numeric(14,2) := 0;
  v_last_month_payments numeric(14,2) := 0;
  v_last_month_expenses numeric(14,2) := 0;
  v_last_month_outgoing numeric(14,2) := 0;
  v_last_month_net_profit numeric(14,2) := 0;

  -- 3. This Year (Financial Year)
  v_fy_label text;
  v_fy_start date;
  v_fy_end date;
  v_year_bills_count int := 0;
  v_year_income numeric(14,2) := 0;
  v_year_payments numeric(14,2) := 0;
  v_year_expenses numeric(14,2) := 0;
  v_year_outgoing numeric(14,2) := 0;
  v_year_net_profit numeric(14,2) := 0;
  v_year_payment_methods jsonb := '{}'::jsonb;
  v_year_top_services jsonb := '[]'::jsonb;
  v_year_chart_data jsonb := '[]'::jsonb;

  -- Year Comparison (Last FY)
  v_last_fy_start date;
  v_last_fy_end date;
  v_last_year_income numeric(14,2) := 0;
  v_last_year_payments numeric(14,2) := 0;
  v_last_year_expenses numeric(14,2) := 0;
  v_last_year_outgoing numeric(14,2) := 0;
  v_last_year_net_profit numeric(14,2) := 0;

  -- Dues & Loans
  v_total_outstanding numeric(14,2) := 0;
  v_loan_outstanding numeric(14,2) := 0;

  -- Jobs
  v_jobs_pending int := 0;
  v_jobs_completed_today int := 0;
  v_jobs_completed_total int := 0;
  v_jobs_late int := 0;
  v_jobs_red int := 0;
  v_jobs_yellow int := 0;

  -- Alerts
  v_overdue_bills_count int := 0;
  v_due_today_bills_count int := 0;

  -- Recent Data
  v_recent_bills jsonb := '[]'::jsonb;
  v_recent_customers jsonb := '[]'::jsonb;
  v_pending_payments jsonb := '[]'::jsonb;
BEGIN
  v_biz_id := (SELECT app.current_business_id());
  v_role := (SELECT app.current_role());
  v_today := (SELECT app.today());

  -- STRICT RBAC: Only OWNER and ACCOUNTANT can access the business-wide dashboard
  IF v_biz_id IS NULL OR v_role NOT IN ('OWNER', 'ACCOUNTANT') THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO v_biz FROM public.businesses WHERE id = v_biz_id;
  v_red_days := COALESCE(v_biz.red_days, 3);
  v_yellow_days := COALESCE(v_biz.yellow_days, 5);

  -- Month range
  v_month_start := date_trunc('month', v_today)::date;
  v_month_end := (date_trunc('month', v_today) + interval '1 month - 1 day')::date;

  -- FY range (Indian Financial Year: 1 Apr to 31 Mar)
  v_fy_label := public.fy_label(v_today);
  IF EXTRACT(MONTH FROM v_today) >= 4 THEN
    v_fy_start := make_date(EXTRACT(YEAR FROM v_today)::int, 4, 1);
    v_fy_end := make_date(EXTRACT(YEAR FROM v_today)::int + 1, 3, 31);
  ELSE
    v_fy_start := make_date(EXTRACT(YEAR FROM v_today)::int - 1, 4, 1);
    v_fy_end := make_date(EXTRACT(YEAR FROM v_today)::int, 3, 31);
  END IF;

  -- =========================================================
  -- 1. TODAY DATA
  -- =========================================================
  SELECT COUNT(*)
  INTO v_today_bills_count
  FROM public.invoices
  WHERE business_id = v_biz_id AND invoice_date = v_today AND status = 'ACTIVE' AND deleted_at IS NULL;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_today_income
  FROM public.receipts
  WHERE business_id = v_biz_id AND receipt_date = v_today AND deleted_at IS NULL;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_today_payments
  FROM public.payments
  WHERE business_id = v_biz_id AND payment_date = v_today AND deleted_at IS NULL;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_today_expenses
  FROM public.expenses
  WHERE business_id = v_biz_id AND expense_date = v_today AND deleted_at IS NULL;

  v_today_outgoing := v_today_payments + v_today_expenses;
  v_today_net_profit := v_today_income - v_today_outgoing;

  -- Today Comparison: Yesterday
  v_yesterday := v_today - 1;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_yesterday_income
  FROM public.receipts
  WHERE business_id = v_biz_id AND receipt_date = v_yesterday AND deleted_at IS NULL;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_yesterday_payments
  FROM public.payments
  WHERE business_id = v_biz_id AND payment_date = v_yesterday AND deleted_at IS NULL;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_yesterday_expenses
  FROM public.expenses
  WHERE business_id = v_biz_id AND expense_date = v_yesterday AND deleted_at IS NULL;

  v_yesterday_outgoing := v_yesterday_payments + v_yesterday_expenses;
  v_yesterday_net_profit := v_yesterday_income - v_yesterday_outgoing;

  -- Today payment methods
  SELECT jsonb_build_object(
    'cash', COALESCE(SUM(amount) FILTER (WHERE mode = 'CASH'), 0),
    'upi', COALESCE(SUM(amount) FILTER (WHERE mode = 'UPI'), 0),
    'bank', COALESCE(SUM(amount) FILTER (WHERE mode IN ('BANK', 'CHEQUE')), 0),
    'card', COALESCE(SUM(amount) FILTER (WHERE mode = 'CARD'), 0),
    'total', COALESCE(SUM(amount), 0)
  )
  INTO v_today_payment_methods
  FROM public.receipts
  WHERE business_id = v_biz_id AND receipt_date = v_today AND deleted_at IS NULL;

  -- Today top services
  SELECT COALESCE(jsonb_agg(sub), '[]'::jsonb)
  INTO v_today_top_services
  FROM (
    SELECT
      COALESCE(s.name, ii.description) as name,
      COUNT(*)::int as count,
      COALESCE(SUM(ii.amount), 0) as total_amount
    FROM public.invoice_items ii
    JOIN public.invoices i ON i.id = ii.invoice_id
    LEFT JOIN public.services s ON s.id = ii.service_id
    WHERE i.business_id = v_biz_id
      AND i.invoice_date = v_today
      AND i.status = 'ACTIVE'
      AND i.deleted_at IS NULL
    GROUP BY COALESCE(s.name, ii.description)
    ORDER BY count DESC, total_amount DESC
    LIMIT 5
  ) sub;

  -- =========================================================
  -- 2. THIS MONTH DATA
  -- =========================================================
  SELECT COUNT(*)
  INTO v_month_bills_count
  FROM public.invoices
  WHERE business_id = v_biz_id
    AND invoice_date >= v_month_start AND invoice_date <= v_month_end
    AND status = 'ACTIVE' AND deleted_at IS NULL;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_month_income
  FROM public.receipts
  WHERE business_id = v_biz_id
    AND receipt_date >= v_month_start AND receipt_date <= v_month_end
    AND deleted_at IS NULL;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_month_payments
  FROM public.payments
  WHERE business_id = v_biz_id
    AND payment_date >= v_month_start AND payment_date <= v_month_end
    AND deleted_at IS NULL;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_month_expenses
  FROM public.expenses
  WHERE business_id = v_biz_id
    AND expense_date >= v_month_start AND expense_date <= v_month_end
    AND deleted_at IS NULL;

  v_month_outgoing := v_month_payments + v_month_expenses;
  v_month_net_profit := v_month_income - v_month_outgoing;

  -- Month Comparison: Last Month
  v_last_month_start := (date_trunc('month', v_today) - interval '1 month')::date;
  v_last_month_end := (date_trunc('month', v_today) - interval '1 day')::date;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_last_month_income
  FROM public.receipts
  WHERE business_id = v_biz_id
    AND receipt_date >= v_last_month_start AND receipt_date <= v_last_month_end
    AND deleted_at IS NULL;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_last_month_payments
  FROM public.payments
  WHERE business_id = v_biz_id
    AND payment_date >= v_last_month_start AND payment_date <= v_last_month_end
    AND deleted_at IS NULL;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_last_month_expenses
  FROM public.expenses
  WHERE business_id = v_biz_id
    AND expense_date >= v_last_month_start AND expense_date <= v_last_month_end
    AND deleted_at IS NULL;

  v_last_month_outgoing := v_last_month_payments + v_last_month_expenses;
  v_last_month_net_profit := v_last_month_income - v_last_month_outgoing;

  -- Month payment methods
  SELECT jsonb_build_object(
    'cash', COALESCE(SUM(amount) FILTER (WHERE mode = 'CASH'), 0),
    'upi', COALESCE(SUM(amount) FILTER (WHERE mode = 'UPI'), 0),
    'bank', COALESCE(SUM(amount) FILTER (WHERE mode IN ('BANK', 'CHEQUE')), 0),
    'card', COALESCE(SUM(amount) FILTER (WHERE mode = 'CARD'), 0),
    'total', COALESCE(SUM(amount), 0)
  )
  INTO v_month_payment_methods
  FROM public.receipts
  WHERE business_id = v_biz_id
    AND receipt_date >= v_month_start AND receipt_date <= v_month_end
    AND deleted_at IS NULL;

  -- Month top services
  SELECT COALESCE(jsonb_agg(sub), '[]'::jsonb)
  INTO v_month_top_services
  FROM (
    SELECT
      COALESCE(s.name, ii.description) as name,
      COUNT(*)::int as count,
      COALESCE(SUM(ii.amount), 0) as total_amount
    FROM public.invoice_items ii
    JOIN public.invoices i ON i.id = ii.invoice_id
    LEFT JOIN public.services s ON s.id = ii.service_id
    WHERE i.business_id = v_biz_id
      AND i.invoice_date >= v_month_start AND i.invoice_date <= v_month_end
      AND i.status = 'ACTIVE'
      AND i.deleted_at IS NULL
    GROUP BY COALESCE(s.name, ii.description)
    ORDER BY count DESC, total_amount DESC
    LIMIT 5
  ) sub;

  -- Month Chart Data: Daily breakdown for current month
  SELECT COALESCE(jsonb_agg(sub), '[]'::jsonb)
  INTO v_month_chart_data
  FROM (
    SELECT
      to_char(d.date, 'DD Mon') as date,
      d.date as raw_date,
      COALESCE((
        SELECT SUM(r.amount)
        FROM public.receipts r
        WHERE r.business_id = v_biz_id AND r.receipt_date = d.date AND r.deleted_at IS NULL
      ), 0) as income,
      COALESCE((
        SELECT SUM(p.amount)
        FROM public.payments p
        WHERE p.business_id = v_biz_id AND p.payment_date = d.date AND p.deleted_at IS NULL
      ), 0) +
      COALESCE((
        SELECT SUM(e.amount)
        FROM public.expenses e
        WHERE e.business_id = v_biz_id AND e.expense_date = d.date AND e.deleted_at IS NULL
      ), 0) as outgoing
    FROM generate_series(v_month_start, v_today, '1 day'::interval) d(date)
    ORDER BY d.date ASC
  ) sub;

  -- =========================================================
  -- 3. THIS YEAR DATA (FY)
  -- =========================================================
  SELECT COUNT(*)
  INTO v_year_bills_count
  FROM public.invoices
  WHERE business_id = v_biz_id
    AND invoice_date >= v_fy_start AND invoice_date <= v_fy_end
    AND status = 'ACTIVE' AND deleted_at IS NULL;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_year_income
  FROM public.receipts
  WHERE business_id = v_biz_id
    AND receipt_date >= v_fy_start AND receipt_date <= v_fy_end
    AND deleted_at IS NULL;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_year_payments
  FROM public.payments
  WHERE business_id = v_biz_id
    AND payment_date >= v_fy_start AND payment_date <= v_fy_end
    AND deleted_at IS NULL;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_year_expenses
  FROM public.expenses
  WHERE business_id = v_biz_id
    AND expense_date >= v_fy_start AND expense_date <= v_fy_end
    AND deleted_at IS NULL;

  v_year_outgoing := v_year_payments + v_year_expenses;
  v_year_net_profit := v_year_income - v_year_outgoing;

  -- Year Comparison: Last Financial Year
  v_last_fy_start := (v_fy_start - interval '1 year')::date;
  v_last_fy_end := (v_fy_start - interval '1 day')::date;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_last_year_income
  FROM public.receipts
  WHERE business_id = v_biz_id
    AND receipt_date >= v_last_fy_start AND receipt_date <= v_last_fy_end
    AND deleted_at IS NULL;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_last_year_payments
  FROM public.payments
  WHERE business_id = v_biz_id
    AND payment_date >= v_last_fy_start AND payment_date <= v_last_fy_end
    AND deleted_at IS NULL;

  SELECT COALESCE(SUM(amount), 0)
  INTO v_last_year_expenses
  FROM public.expenses
  WHERE business_id = v_biz_id
    AND expense_date >= v_last_fy_start AND expense_date <= v_last_fy_end
    AND deleted_at IS NULL;

  v_last_year_outgoing := v_last_year_payments + v_last_year_expenses;
  v_last_year_net_profit := v_last_year_income - v_last_year_outgoing;

  -- Year payment methods
  SELECT jsonb_build_object(
    'cash', COALESCE(SUM(amount) FILTER (WHERE mode = 'CASH'), 0),
    'upi', COALESCE(SUM(amount) FILTER (WHERE mode = 'UPI'), 0),
    'bank', COALESCE(SUM(amount) FILTER (WHERE mode IN ('BANK', 'CHEQUE')), 0),
    'card', COALESCE(SUM(amount) FILTER (WHERE mode = 'CARD'), 0),
    'total', COALESCE(SUM(amount), 0)
  )
  INTO v_year_payment_methods
  FROM public.receipts
  WHERE business_id = v_biz_id
    AND receipt_date >= v_fy_start AND receipt_date <= v_fy_end
    AND deleted_at IS NULL;

  -- Year top services
  SELECT COALESCE(jsonb_agg(sub), '[]'::jsonb)
  INTO v_year_top_services
  FROM (
    SELECT
      COALESCE(s.name, ii.description) as name,
      COUNT(*)::int as count,
      COALESCE(SUM(ii.amount), 0) as total_amount
    FROM public.invoice_items ii
    JOIN public.invoices i ON i.id = ii.invoice_id
    LEFT JOIN public.services s ON s.id = ii.service_id
    WHERE i.business_id = v_biz_id
      AND i.invoice_date >= v_fy_start AND i.invoice_date <= v_fy_end
      AND i.status = 'ACTIVE'
      AND i.deleted_at IS NULL
    GROUP BY COALESCE(s.name, ii.description)
    ORDER BY count DESC, total_amount DESC
    LIMIT 5
  ) sub;

  -- Year Chart Data: Monthly breakdown for financial year
  SELECT COALESCE(jsonb_agg(sub), '[]'::jsonb)
  INTO v_year_chart_data
  FROM (
    SELECT
      to_char(m.date, 'Mon YYYY') as date,
      m.date as raw_date,
      COALESCE((
        SELECT SUM(r.amount)
        FROM public.receipts r
        WHERE r.business_id = v_biz_id
          AND r.receipt_date >= m.date::date
          AND r.receipt_date < (m.date + '1 month'::interval)::date
          AND r.deleted_at IS NULL
      ), 0) as income,
      COALESCE((
        SELECT SUM(p.amount)
        FROM public.payments p
        WHERE p.business_id = v_biz_id
          AND p.payment_date >= m.date::date
          AND p.payment_date < (m.date + '1 month'::interval)::date
          AND p.deleted_at IS NULL
      ), 0) +
      COALESCE((
        SELECT SUM(e.amount)
        FROM public.expenses e
        WHERE e.business_id = v_biz_id
          AND e.expense_date >= m.date::date
          AND e.expense_date < (m.date + '1 month'::interval)::date
          AND e.deleted_at IS NULL
      ), 0) as outgoing
    FROM generate_series(v_fy_start, v_today, '1 month'::interval) m(date)
    ORDER BY m.date ASC
  ) sub;

  -- =========================================================
  -- 4. DUES & LOANS
  -- =========================================================
  SELECT COALESCE(SUM(total - paid_amount), 0)
  INTO v_total_outstanding
  FROM public.invoices
  WHERE business_id = v_biz_id
    AND status = 'ACTIVE'
    AND total > paid_amount
    AND deleted_at IS NULL;

  SELECT COALESCE(
    (SELECT SUM(amount) FROM public.loans WHERE business_id = v_biz_id AND deleted_at IS NULL), 0
  ) - COALESCE(
    (SELECT SUM(lr.principal) FROM public.loan_repayments lr JOIN public.loans l ON l.id = lr.loan_id WHERE l.business_id = v_biz_id AND lr.deleted_at IS NULL), 0
  ) INTO v_loan_outstanding;

  -- =========================================================
  -- 5. JOBS
  -- =========================================================
  IF v_biz.job_management_enabled THEN
    SELECT COUNT(*) INTO v_jobs_pending
    FROM public.jobs
    WHERE business_id = v_biz_id AND status = 'IN_PROGRESS' AND deleted_at IS NULL;

    SELECT COUNT(*) INTO v_jobs_completed_today
    FROM public.jobs
    WHERE business_id = v_biz_id AND status = 'COMPLETED' AND completed_at::date = v_today AND deleted_at IS NULL;

    SELECT COUNT(*) INTO v_jobs_completed_total
    FROM public.jobs
    WHERE business_id = v_biz_id AND status = 'COMPLETED' AND deleted_at IS NULL;

    SELECT COUNT(*) INTO v_jobs_late
    FROM public.jobs
    WHERE business_id = v_biz_id
      AND status = 'IN_PROGRESS'
      AND deadline_date < v_today
      AND deleted_at IS NULL;

    SELECT COUNT(*) INTO v_jobs_red
    FROM public.jobs
    WHERE business_id = v_biz_id
      AND status = 'IN_PROGRESS'
      AND deadline_date >= v_today
      AND (deadline_date - v_today) <= v_red_days
      AND deleted_at IS NULL;

    SELECT COUNT(*) INTO v_jobs_yellow
    FROM public.jobs
    WHERE business_id = v_biz_id
      AND status = 'IN_PROGRESS'
      AND (deadline_date - v_today) > v_red_days
      AND (deadline_date - v_today) <= v_yellow_days
      AND deleted_at IS NULL;
  END IF;

  -- =========================================================
  -- 6. ALERTS
  -- =========================================================
  SELECT COUNT(*)
  INTO v_overdue_bills_count
  FROM public.invoices
  WHERE business_id = v_biz_id
    AND status = 'ACTIVE'
    AND total > paid_amount
    AND due_date < v_today
    AND deleted_at IS NULL;

  SELECT COUNT(*)
  INTO v_due_today_bills_count
  FROM public.invoices
  WHERE business_id = v_biz_id
    AND status = 'ACTIVE'
    AND total > paid_amount
    AND due_date = v_today
    AND deleted_at IS NULL;

  -- =========================================================
  -- 7. RECENT DATA
  -- =========================================================
  SELECT COALESCE(jsonb_agg(sub), '[]'::jsonb)
  INTO v_recent_bills
  FROM (
    SELECT
      id, number, invoice_date, due_date, party_name, party_mobile,
      total, paid_amount, (total - paid_amount) as balance, status, created_at
    FROM public.invoices
    WHERE business_id = v_biz_id AND deleted_at IS NULL
    ORDER BY created_at DESC
    LIMIT 6
  ) sub;

  SELECT COALESCE(jsonb_agg(sub), '[]'::jsonb)
  INTO v_recent_customers
  FROM (
    SELECT id, name, mobile, type, created_at
    FROM public.customers
    WHERE business_id = v_biz_id AND deleted_at IS NULL
    ORDER BY created_at DESC
    LIMIT 5
  ) sub;

  SELECT COALESCE(jsonb_agg(sub), '[]'::jsonb)
  INTO v_pending_payments
  FROM (
    SELECT
      id, number, party_name, party_mobile, total, paid_amount,
      (total - paid_amount) as balance, due_date
    FROM public.invoices
    WHERE business_id = v_biz_id
      AND status = 'ACTIVE'
      AND total > paid_amount
      AND due_date < v_today
      AND deleted_at IS NULL
    ORDER BY due_date ASC
    LIMIT 5
  ) sub;

  RETURN jsonb_build_object(
    'today', jsonb_build_object(
      'label', 'Today',
      'date', v_today,
      'bills_count', v_today_bills_count,
      'income', v_today_income,
      'payments', v_today_payments,
      'expenses', v_today_expenses,
      'outgoing', v_today_outgoing,
      'net_profit', v_today_net_profit,
      'payment_methods', v_today_payment_methods,
      'top_services', v_today_top_services,
      'chart_data', v_today_chart_data,
      'total_outstanding', v_total_outstanding,
      'loan_outstanding', v_loan_outstanding,
      'prev_income', v_yesterday_income,
      'prev_outgoing', v_yesterday_outgoing,
      'prev_net_profit', v_yesterday_net_profit,
      'comparison_label', 'vs yesterday'
    ),
    'this_month', jsonb_build_object(
      'label', 'This Month',
      'month_label', to_char(v_today, 'Mon YYYY'),
      'start_date', v_month_start,
      'end_date', v_month_end,
      'bills_count', v_month_bills_count,
      'income', v_month_income,
      'payments', v_month_payments,
      'expenses', v_month_expenses,
      'outgoing', v_month_outgoing,
      'net_profit', v_month_net_profit,
      'payment_methods', v_month_payment_methods,
      'top_services', v_month_top_services,
      'chart_data', v_month_chart_data,
      'total_outstanding', v_total_outstanding,
      'loan_outstanding', v_loan_outstanding,
      'prev_income', v_last_month_income,
      'prev_outgoing', v_last_month_outgoing,
      'prev_net_profit', v_last_month_net_profit,
      'comparison_label', 'vs last month'
    ),
    'this_year', jsonb_build_object(
      'label', 'This Year',
      'fy_label', v_fy_label,
      'start_date', v_fy_start,
      'end_date', v_fy_end,
      'bills_count', v_year_bills_count,
      'income', v_year_income,
      'payments', v_year_payments,
      'expenses', v_year_expenses,
      'outgoing', v_year_outgoing,
      'net_profit', v_year_net_profit,
      'payment_methods', v_year_payment_methods,
      'top_services', v_year_top_services,
      'chart_data', v_year_chart_data,
      'total_outstanding', v_total_outstanding,
      'loan_outstanding', v_loan_outstanding,
      'prev_income', v_last_year_income,
      'prev_outgoing', v_last_year_outgoing,
      'prev_net_profit', v_last_year_net_profit,
      'comparison_label', 'vs last year'
    ),
    'jobs', jsonb_build_object(
      'enabled', v_biz.job_management_enabled,
      'pending', v_jobs_pending,
      'completed_today', v_jobs_completed_today,
      'completed_total', v_jobs_completed_total,
      'late_count', v_jobs_late,
      'red_count', v_jobs_red,
      'yellow_count', v_jobs_yellow,
      'red_days', v_red_days,
      'yellow_days', v_yellow_days
    ),
    'alerts', jsonb_build_object(
      'overdue_bills_count', v_overdue_bills_count,
      'due_today_bills_count', v_due_today_bills_count
    ),
    'recent_bills', v_recent_bills,
    'recent_customers', v_recent_customers,
    'pending_payments', v_pending_payments
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = '';


-- >>> Migration: 20261123000057_receipt_detail_include_items.sql <<<
-- ==============================================================================
-- Migration: 20261123000057_receipt_detail_include_items.sql
-- Description: Update receipt_detail function to include invoice items and particulars
-- ==============================================================================

CREATE OR REPLACE FUNCTION public.receipt_detail(p_receipt_id uuid)
RETURNS jsonb AS $$
DECLARE
  v_biz_id uuid;
  v_receipt public.receipts%ROWTYPE;
  v_cust public.customers%ROWTYPE;
  v_biz public.businesses%ROWTYPE;
  v_allocs jsonb := '[]'::jsonb;
  v_cust_current_due numeric(14,2) := 0;
  v_allocated_total numeric(14,2) := 0;
  v_ledger_summary jsonb := NULL;
  v_walkin_name text;
  v_walkin_mobile text;
  v_bank_name text;
BEGIN
  v_biz_id := (SELECT app.current_business_id());

  SELECT * INTO v_receipt
  FROM public.receipts
  WHERE id = p_receipt_id AND business_id = v_biz_id AND deleted_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'RECEIPT_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  -- Lookup bank name if bank_id is present
  IF v_receipt.bank_id IS NOT NULL THEN
    SELECT name INTO v_bank_name
    FROM public.bank_accounts
    WHERE id = v_receipt.bank_id AND business_id = v_biz_id;
  END IF;

  IF v_receipt.customer_id IS NOT NULL THEN
    SELECT * INTO v_cust
    FROM public.customers
    WHERE id = v_receipt.customer_id AND business_id = v_biz_id;

    -- Calculate current customer remaining dues across active bills
    SELECT COALESCE(SUM(i.total - i.paid_amount), 0)
    INTO v_cust_current_due
    FROM public.invoices i
    WHERE i.customer_id = v_receipt.customer_id
      AND i.business_id = v_biz_id
      AND i.status = 'ACTIVE'
      AND i.deleted_at IS NULL;

    -- Calculate total allocated from this receipt
    SELECT COALESCE(SUM(amount), 0)
    INTO v_allocated_total
    FROM public.receipt_allocations
    WHERE receipt_id = v_receipt.id;

    v_ledger_summary := jsonb_build_object(
      'previous_due', v_cust_current_due + v_allocated_total,
      'amount_paid', v_receipt.amount,
      'allocated_to_bills', v_allocated_total,
      'remaining_due', v_cust_current_due,
      'customer_advance', COALESCE(v_receipt.unallocated_amount, 0)
    );
  ELSE
    -- For walk-in receipts without customer record: check invoice party snapshot
    SELECT i.party_name, i.party_mobile
    INTO v_walkin_name, v_walkin_mobile
    FROM public.receipt_allocations ra
    JOIN public.invoices i ON i.id = ra.invoice_id
    WHERE ra.receipt_id = v_receipt.id
    ORDER BY ra.created_at ASC
    LIMIT 1;

    IF v_walkin_name IS NOT NULL THEN
      v_cust.name := v_walkin_name;
      v_cust.mobile := v_walkin_mobile;
    ELSIF v_receipt.kind = 'OTHER_INCOME' THEN
      v_cust.name := COALESCE(v_receipt.income_category, 'Other Income');
    ELSE
      v_cust.name := 'Direct / Walk-in Customer';
    END IF;
  END IF;

  SELECT * INTO v_biz
  FROM public.businesses
  WHERE id = v_biz_id;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', ra.id,
      'invoice_id', ra.invoice_id,
      'invoice_number', i.number,
      'invoice_date', i.invoice_date,
      'invoice_total', i.total,
      'allocated_amount', ra.amount,
      'invoice_balance', (i.total - i.paid_amount),
      'items', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', ii.id,
            'description', ii.description,
            'quantity', ii.quantity,
            'rate', ii.rate,
            'amount', ii.amount,
            'applicant_name', ii.applicant_name
          )
        )
        FROM public.invoice_items ii
        WHERE ii.invoice_id = i.id
      ), '[]'::jsonb)
    )
    ORDER BY i.invoice_date ASC, i.created_at ASC
  ), '[]'::jsonb)
  INTO v_allocs
  FROM public.receipt_allocations ra
  JOIN public.invoices i ON i.id = ra.invoice_id
  WHERE ra.receipt_id = v_receipt.id;

  RETURN jsonb_build_object(
    'receipt', jsonb_set(to_jsonb(v_receipt), '{bank_name}', to_jsonb(COALESCE(v_bank_name, ''))),
    'customer', jsonb_build_object(
      'id', v_cust.id,
      'name', COALESCE(v_cust.name, 'Customer'),
      'mobile', v_cust.mobile,
      'address', v_cust.address,
      'type', v_cust.type
    ),
    'allocations', v_allocs,
    'ledger_summary', v_ledger_summary,
    'business', jsonb_build_object(
      'id', v_biz.id,
      'name', v_biz.name,
      'owner_name', v_biz.owner_name,
      'mobile', v_biz.mobile,
      'email', v_biz.email,
      'address', v_biz.address,
      'upi_id', v_biz.upi_id,
      'receipt_header', v_biz.receipt_header,
      'receipt_footer', v_biz.receipt_footer
    )
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = '';

REVOKE ALL ON FUNCTION public.receipt_detail(uuid) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.receipt_detail(uuid) TO authenticated;


